def expand_contractions(text, contraction_map=dict):
    contractions_pattern = re.compile('({})'.format('|'.join((re.escape(k) for k in contraction_map.keys()))), flags=re.IGNORECASE | re.DOTALL)

    def expand_match(contraction):
        match = contraction.group(0)
        lower_match = match.lower()
        expanded_contraction = contraction_map.get(match) or contraction_map.get(lower_match)
        if expanded_contraction:
            if match[0].isupper():
                return expanded_contraction[0].upper() + expanded_contraction[1:]
            else:
                return expanded_contraction
        else:
            return match
